UPDATE world.creature_text SET Text='Mograine has fallen! You shall pay for this treachery! Arise, my champion! Arise!', BroadcastTextId=18023, Sound=5838 WHERE CreatureID=3977 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Arise, my champion!', BroadcastTextId=6532, Sound=5840 WHERE CreatureID=3977 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Who dares disturb my meditation?', BroadcastTextId=6171, Sound=5802 WHERE CreatureID=4832 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Sleep...', BroadcastTextId=0, Sound=5804 WHERE CreatureID=4832 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Dust to dust.', BroadcastTextId=6172, Sound=5803 WHERE CreatureID=4832 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Me Grimlok, king!', BroadcastTextId=6213, Sound=5853 WHERE CreatureID=4854 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Die! Die!', BroadcastTextId=6214, Sound=5854 WHERE CreatureID=4854 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Your reign of terror ends now! Face your doom, mortals!', BroadcastTextId=270001, Sound=0 WHERE CreatureID=9156 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Ow!  OK, I''ll get back to work, $n!', BroadcastTextId=5774, Sound=7514 WHERE CreatureID=10556 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='OK boss, I get back to tree-hitting.', BroadcastTextId=40937, Sound=7514 WHERE CreatureID=10556 AND GroupID=0 AND ID=2;
UPDATE world.creature_text SET Text='Just was resting eyes!  Back to work now!', BroadcastTextId=40938, Sound=7514 WHERE CreatureID=10556 AND GroupID=0 AND ID=3;
UPDATE world.creature_text SET Text='Sleepy... so sleepy...', BroadcastTextId=40936, Sound=7514 WHERE CreatureID=10556 AND GroupID=0 AND ID=4;
UPDATE world.creature_text SET Text='Start running!', BroadcastTextId=5966, Sound=6280 WHERE CreatureID=10599 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Bring it on!', BroadcastTextId=5967, Sound=6281 WHERE CreatureID=10599 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Do not push me, or I will impale you on my horns!', BroadcastTextId=5968, Sound=6277 WHERE CreatureID=10600 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='%s summons a Blackhand Dreadweaver to his aid!', BroadcastTextId=0, Sound=0 WHERE CreatureID=10680 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='%s summons a Blackhand Veteran to his aid!', BroadcastTextId=0, Sound=0 WHERE CreatureID=10681 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Liladris has been waiting for me at Maestra''s Post, so we should make haste, $n.', BroadcastTextId=6540, Sound=6209 WHERE CreatureID=11218 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Ding!', BroadcastTextId=52032, Sound=0 WHERE CreatureID=11382 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='None of your kind should be here!  You''ve doomed only yourselves!', BroadcastTextId=9967, Sound=8286 WHERE CreatureID=12017 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Clever, mortals - but I am not so easily lured away from my sanctum!', BroadcastTextId=9968, Sound=8287 WHERE CreatureID=12017 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I can sense the shadow on your hearts. There can be no rest for the wicked!', BroadcastTextId=106179, Sound=0 WHERE CreatureID=14888 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Your wicked souls shall feed my power!', BroadcastTextId=106180, Sound=0 WHERE CreatureID=14888 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Peace is but a fleeting dream! Let the Nightmare reign!', BroadcastTextId=106181, Sound=0 WHERE CreatureID=14890 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Children of madness! I release you upon this world!', BroadcastTextId=106182, Sound=0 WHERE CreatureID=14890 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='You will be judged for defiling these sacred grounds!  The laws of the Ancients will not be challenged!  Trespassers will be annihilated!
', BroadcastTextId=11442, Sound=8646 WHERE CreatureID=15516 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='I sentence you to death!', BroadcastTextId=11443, Sound=8647 WHERE CreatureID=15516 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I serve to the last!', BroadcastTextId=11444, Sound=8648 WHERE CreatureID=15516 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Madness has brought you here to me. I shall be your undoing!', BroadcastTextId=15127, Sound=9218 WHERE CreatureID=15690 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Simple fools! Time is the fire in which you''ll burn!', BroadcastTextId=15341, Sound=9220 WHERE CreatureID=15690 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I see the subtlety of conception is beyond primitives such as you.', BroadcastTextId=0, Sound=9317 WHERE CreatureID=15690 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Who knows what secrets hide in the dark.', BroadcastTextId=0, Sound=9223 WHERE CreatureID=15690 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='The cerestial forces are mine to manipulate.', BroadcastTextId=0, Sound=9320 WHERE CreatureID=15690 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='How can you hope to stand against such overwhelming power?', BroadcastTextId=15342, Sound=9321 WHERE CreatureID=15690 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='Surely you did not think you could win.', BroadcastTextId=15124, Sound=9222 WHERE CreatureID=15690 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='Your greed, your foolishness has brought you to this end.', BroadcastTextId=15125, Sound=9318 WHERE CreatureID=15690 AND GroupID=6 AND ID=1;
UPDATE world.creature_text SET Text='You are but a plaything. Unfit even to amuse.', BroadcastTextId=15126, Sound=9319 WHERE CreatureID=15690 AND GroupID=6 AND ID=2;
UPDATE world.creature_text SET Text='All realities, all dimensions are open to me!', BroadcastTextId=15343, Sound=9224 WHERE CreatureID=15690 AND GroupID=7 AND ID=0;
UPDATE world.creature_text SET Text='You face not Malchezaar alone, but the legions I command!', BroadcastTextId=15344, Sound=9322 WHERE CreatureID=15690 AND GroupID=7 AND ID=1;
UPDATE world.creature_text SET Text='I refuse to concede defeat! I am a prince of the Eredar! I... am...', BroadcastTextId=15123, Sound=9221 WHERE CreatureID=15690 AND GroupID=8 AND ID=0;
UPDATE world.creature_text SET Text='You are mine now.', BroadcastTextId=13041, Sound=8825 WHERE CreatureID=15936 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='I see you...', BroadcastTextId=13042, Sound=8826 WHERE CreatureID=15936 AND GroupID=0 AND ID=1;
UPDATE world.creature_text SET Text='You... are next.', BroadcastTextId=13043, Sound=8827 WHERE CreatureID=15936 AND GroupID=0 AND ID=2;
UPDATE world.creature_text SET Text='Close your eyes. Sleep.', BroadcastTextId=13045, Sound=8829 WHERE CreatureID=15936 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='The races of the world will perish. It is only a matter of time.', BroadcastTextId=13046, Sound=8830 WHERE CreatureID=15936 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='I see endless suffering. I see torment. I see rage. I see everything...', BroadcastTextId=13047, Sound=8831 WHERE CreatureID=15936 AND GroupID=2 AND ID=1;
UPDATE world.creature_text SET Text='Soon the world will tremble.', BroadcastTextId=13048, Sound=8832 WHERE CreatureID=15936 AND GroupID=2 AND ID=2;
UPDATE world.creature_text SET Text='The end is upon you.', BroadcastTextId=13049, Sound=8833 WHERE CreatureID=15936 AND GroupID=2 AND ID=3;
UPDATE world.creature_text SET Text='Hungry worms will feast on your rotting flesh.', BroadcastTextId=13050, Sound=8834 WHERE CreatureID=15936 AND GroupID=2 AND ID=4;
UPDATE world.creature_text SET Text='Noo... o...', BroadcastTextId=0, Sound=8828 WHERE CreatureID=15936 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Glory to the master!', BroadcastTextId=13061, Sound=8845 WHERE CreatureID=15954 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Your life is forfeit!', BroadcastTextId=13062, Sound=8846 WHERE CreatureID=15954 AND GroupID=0 AND ID=1;
UPDATE world.creature_text SET Text='Die, trespasser!', BroadcastTextId=13063, Sound=8847 WHERE CreatureID=15954 AND GroupID=0 AND ID=2;
UPDATE world.creature_text SET Text='Rise, my soldiers! Rise and fight once more!', BroadcastTextId=13067, Sound=8851 WHERE CreatureID=15954 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='My task is done!', BroadcastTextId=13065, Sound=8849 WHERE CreatureID=15954 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Breathe no more!', BroadcastTextId=13066, Sound=8850 WHERE CreatureID=15954 AND GroupID=2 AND ID=1;
UPDATE world.creature_text SET Text='I will serve the master... in death!', BroadcastTextId=13064, Sound=8848 WHERE CreatureID=15954 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='It is good that you serve me so faithfully. Soon, all will serve the Lich King and in the end, you shall be rewarded...so long as you do not falter.', BroadcastTextId=0, Sound=8881 WHERE CreatureID=15990 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Your security measures have failed! See to this interruption immediately!', BroadcastTextId=0, Sound=8882 WHERE CreatureID=15990 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Defend yourself!', BroadcastTextId=13010, Sound=8892 WHERE CreatureID=16065 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='The first kill goes to me! Anyone care to wager?', BroadcastTextId=13016, Sound=8898 WHERE CreatureID=16065 AND GroupID=1 AND ID=2;
UPDATE world.creature_text SET Text='Your life is mine!', BroadcastTextId=13013, Sound=8895 WHERE CreatureID=16065 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Who''s next?', BroadcastTextId=13012, Sound=8894 WHERE CreatureID=16065 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Touche...', BroadcastTextId=13011, Sound=8893 WHERE CreatureID=16065 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='Come, Zeliek, do not drive them out. Not before we''ve had our fun!', BroadcastTextId=13014, Sound=8896 WHERE CreatureID=16065 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='I do hope they stay alive long enough for me to... introduce myself.', BroadcastTextId=13015, Sound=8897 WHERE CreatureID=16065 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='%s gasps.', BroadcastTextId=0, Sound=0 WHERE CreatureID=16578 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Miserable vermin. I shall exterminate you from the air!', BroadcastTextId=123783, Sound=0 WHERE CreatureID=17225 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='The better to own you with!', BroadcastTextId=14212, Sound=9276 WHERE CreatureID=17521 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Mmmm... delicious.', BroadcastTextId=15153, Sound=9277 WHERE CreatureID=17521 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Run away little girl, run away!', BroadcastTextId=14213, Sound=9278 WHERE CreatureID=17521 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='You mustn''t let him loose!', BroadcastTextId=17673, Sound=10166 WHERE CreatureID=17653 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Ignorant whelps!', BroadcastTextId=17674, Sound=10167 WHERE CreatureID=17653 AND GroupID=0 AND ID=1;
UPDATE world.creature_text SET Text='You fools! He''ll kill us all!', BroadcastTextId=17675, Sound=10168 WHERE CreatureID=17653 AND GroupID=0 AND ID=2;
UPDATE world.creature_text SET Text='Invaders have breached the defenses!', BroadcastTextId=14309, Sound=10285 WHERE CreatureID=17693 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Thrall! You didn''t really think you would escape, did you?  You and your allies shall answer to Blackmoore... after I''ve had my fun.', BroadcastTextId=15909, Sound=10406 WHERE CreatureID=17862 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='You''re a slave! That''s all you''ll ever be!', BroadcastTextId=16673, Sound=10407 WHERE CreatureID=17862 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I don''t know what Blackmoore sees in you. For my money you''re just another ignorant savage!', BroadcastTextId=16674, Sound=10408 WHERE CreatureID=17862 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Thrall will never be free!', BroadcastTextId=16675, Sound=10409 WHERE CreatureID=17862 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Did you really think you would leave here alive?', BroadcastTextId=16676, Sound=10410 WHERE CreatureID=17862 AND GroupID=3 AND ID=1;
UPDATE world.creature_text SET Text='Guards... guards!', BroadcastTextId=16677, Sound=10411 WHERE CreatureID=17862 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='The time has come to shatter this clockwork universe forever! Let us no longer be slaves of the hourglass! I warn you: those who do not embrace this greater path shall become victims of its passing!', BroadcastTextId=16827, Sound=10400 WHERE CreatureID=17881 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Your time is up, slave of the past.', BroadcastTextId=16829, Sound=10401 WHERE CreatureID=17881 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Let us see what fate has in store....', BroadcastTextId=16828, Sound=10402 WHERE CreatureID=17881 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='One less obstacle in our way!', BroadcastTextId=16831, Sound=10403 WHERE CreatureID=17881 AND GroupID=3 AND ID=0;
