', BroadcastTextId=17152, Sound=10630 WHERE CreatureID=18076 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Woe to each and every one of you, my pretties!', BroadcastTextId=15050, Sound=9179 WHERE CreatureID=18168 AND GroupID=0 AND ID=0;
