UPDATE world.creature_text SET Text='Fixed you, didn''t I?', BroadcastTextId=15051, Sound=9180 WHERE CreatureID=18168 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='What is this? You must forgive me, but I was not expecting company. As you can see, we are somewhat preoccupied right now. But no matter. As I am a gracious host, I will tend to you... personally.', BroadcastTextId=17784, Sound=10539 WHERE CreatureID=18344 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='We have not been properly introduced.', BroadcastTextId=17780, Sound=10541 WHERE CreatureID=18344 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='An epic battle, how exciting!', BroadcastTextId=17781, Sound=10542 WHERE CreatureID=18344 AND GroupID=1 AND ID=1;
UPDATE world.creature_text SET Text='I''ve longed for a good adventure!', BroadcastTextId=17782, Sound=10543 WHERE CreatureID=18344 AND GroupID=1 AND ID=2;
UPDATE world.creature_text SET Text='It has been... entertaining.', BroadcastTextId=17779, Sound=10544 WHERE CreatureID=18344 AND GroupID=2 AND ID=0;
