UPDATE world.creature_text SET Text='Hurry up with that axe, you! I want it sharp enough to cut the wind!', BroadcastTextId=16532, Sound=1040 WHERE CreatureID=19380 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Smash!', BroadcastTextId=14046, Sound=10306 WHERE CreatureID=19523 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Hey!', BroadcastTextId=16917, Sound=10307 WHERE CreatureID=19523 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='If you nice me let you live.', BroadcastTextId=14048, Sound=10308 WHERE CreatureID=19523 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Me hungry.', BroadcastTextId=16918, Sound=10309 WHERE CreatureID=19523 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Me not like this one...', BroadcastTextId=14043, Sound=10300 WHERE CreatureID=19523 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='We kill his friend!', BroadcastTextId=14045, Sound=10301 WHERE CreatureID=19523 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='We kill someone else!', BroadcastTextId=16895, Sound=10302 WHERE CreatureID=19523 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='You stay here.  Me go kill someone else!', BroadcastTextId=16898, Sound=10303 WHERE CreatureID=19523 AND GroupID=7 AND ID=0;
UPDATE world.creature_text SET Text='Ha ha ha.', BroadcastTextId=16900, Sound=10304 WHERE CreatureID=19523 AND GroupID=8 AND ID=0;
UPDATE world.creature_text SET Text='Me get bored.', BroadcastTextId=16902, Sound=10305 WHERE CreatureID=19523 AND GroupID=9 AND ID=0;
UPDATE world.creature_text SET Text='This one die easy!', BroadcastTextId=16922, Sound=10310 WHERE CreatureID=19523 AND GroupID=10 AND ID=0;
UPDATE world.creature_text SET Text='This all... your fault!', BroadcastTextId=16924, Sound=10311 WHERE CreatureID=19523 AND GroupID=11 AND ID=0;
UPDATE world.creature_text SET Text='Why don''t you let me do the talking?', BroadcastTextId=14047, Sound=10317 WHERE CreatureID=19524 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='No, we will NOT let you live.', BroadcastTextId=16916, Sound=10318 WHERE CreatureID=19524 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='You''re always hungry.  That''s why we so fat!', BroadcastTextId=16919, Sound=10319 WHERE CreatureID=19524 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Hey, you numbskull!', BroadcastTextId=14044, Sound=10312 WHERE CreatureID=19524 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='I''m not done yet, idiot!', BroadcastTextId=16896, Sound=10313 WHERE CreatureID=19524 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='That''s not funny!', BroadcastTextId=16899, Sound=10314 WHERE CreatureID=19524 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='What are you doing?', BroadcastTextId=16901, Sound=10315 WHERE CreatureID=19524 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='Bored? He was almost dead!', BroadcastTextId=16903, Sound=10316 WHERE CreatureID=19524 AND GroupID=7 AND ID=0;
UPDATE world.creature_text SET Text='I''m tired.  You kill next one!', BroadcastTextId=16921, Sound=10320 WHERE CreatureID=19524 AND GroupID=8 AND ID=0;
UPDATE world.creature_text SET Text='That''s because I do all the hard work!', BroadcastTextId=16923, Sound=10321 WHERE CreatureID=19524 AND GroupID=9 AND ID=0;
UPDATE world.creature_text SET Text='I... hate... you.', BroadcastTextId=16925, Sound=10322 WHERE CreatureID=19524 AND GroupID=10 AND ID=0;
UPDATE world.creature_text SET Text='By the power of the sun!', BroadcastTextId=198071, Sound=0 WHERE CreatureID=19622 AND GroupID=9 AND ID=0;
UPDATE world.creature_text SET Text='No, old friend. You''ve freed us all...', BroadcastTextId=17153, Sound=10631 WHERE CreatureID=19647 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Ohh, look! Bloodmaul Brew! Mmmm...', BroadcastTextId=18170, Sound=398 WHERE CreatureID=19995 AND GroupID=4 AND ID=2;
UPDATE world.creature_text SET Text='Don''t worry about me; kill that worthless dullard instead!', BroadcastTextId=19979, Sound=11085 WHERE CreatureID=20885 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='It is unwise to anger me!', BroadcastTextId=19978, Sound=11086 WHERE CreatureID=20885 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Completely ineffective.  Just like someone else I know.', BroadcastTextId=19980, Sound=11087 WHERE CreatureID=20885 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='You chose the wrong opponent.', BroadcastTextId=19981, Sound=11088 WHERE CreatureID=20885 AND GroupID=2 AND ID=1;
UPDATE world.creature_text SET Text='Reap the whirlwind!', BroadcastTextId=19982, Sound=11089 WHERE CreatureID=20885 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='I''ll cut you to pieces!', BroadcastTextId=19983, Sound=11090 WHERE CreatureID=20885 AND GroupID=3 AND ID=1;
UPDATE world.creature_text SET Text='That is much better.', BroadcastTextId=19984, Sound=11091 WHERE CreatureID=20885 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='Ahh... just what I needed.', BroadcastTextId=19985, Sound=11092 WHERE CreatureID=20885 AND GroupID=4 AND ID=1;
UPDATE world.creature_text SET Text='Now I''m really angry.', BroadcastTextId=19986, Sound=11093 WHERE CreatureID=20885 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='More than you can handle, scryer?', BroadcastTextId=19987, Sound=11094 WHERE CreatureID=20885 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='I suppose I''ll end up fighting them all myself.', BroadcastTextId=19988, Sound=11095 WHERE CreatureID=20885 AND GroupID=6 AND ID=1;
UPDATE world.creature_text SET Text='I''ve grown used to cleaning up your messes.', BroadcastTextId=19989, Sound=11096 WHERE CreatureID=20885 AND GroupID=6 AND ID=2;
UPDATE world.creature_text SET Text='Congratulations.  I''ve wanted to do that for years.', BroadcastTextId=19990, Sound=11097 WHERE CreatureID=20885 AND GroupID=7 AND ID=0;
UPDATE world.creature_text SET Text='Have you come to kill Dalliah?  Can I watch?', BroadcastTextId=19968, Sound=11237 WHERE CreatureID=20886 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='At last, a target for my frustrations!', BroadcastTextId=19967, Sound=11238 WHERE CreatureID=20886 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Yes, that was quite satisfying.', BroadcastTextId=19969, Sound=11239 WHERE CreatureID=20886 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='On guard!', BroadcastTextId=19971, Sound=11241 WHERE CreatureID=20886 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Defend yourself, for all the good it will do....', BroadcastTextId=19972, Sound=11242 WHERE CreatureID=20886 AND GroupID=3 AND ID=1;
UPDATE world.creature_text SET Text='Knew this was... the only way out.', BroadcastTextId=19973, Sound=11243 WHERE CreatureID=20886 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='Having problems, Dalliah?  How nice.', BroadcastTextId=19974, Sound=11244 WHERE CreatureID=20886 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='This may be the end for you, Dalliah.  What a shame that would be.', BroadcastTextId=19975, Sound=11245 WHERE CreatureID=20886 AND GroupID=5 AND ID=1;
UPDATE world.creature_text SET Text='I suggest a new strategy: you draw their attacks while I gather reinforcements.', BroadcastTextId=19976, Sound=11246 WHERE CreatureID=20886 AND GroupID=5 AND ID=2;
UPDATE world.creature_text SET Text='Finally!  Well done!', BroadcastTextId=19977, Sound=11247 WHERE CreatureID=20886 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='Did you call on me?', BroadcastTextId=20051, Sound=11236 WHERE CreatureID=20886 AND GroupID=7 AND ID=0;
UPDATE world.creature_text SET Text='Be gone, trifling elf.  I am in control now!', BroadcastTextId=19595, Sound=11304 WHERE CreatureID=21215 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='We all have our demons....', BroadcastTextId=19597, Sound=11305 WHERE CreatureID=21215 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I have no equal!', BroadcastTextId=19993, Sound=11306 WHERE CreatureID=21215 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Perish, mortal!', BroadcastTextId=19994, Sound=11307 WHERE CreatureID=21215 AND GroupID=2 AND ID=1;
UPDATE world.creature_text SET Text='Yes... yes!', BroadcastTextId=19995, Sound=11308 WHERE CreatureID=21215 AND GroupID=2 AND ID=2;
UPDATE world.creature_text SET Text='Finally, my banishment ends!', BroadcastTextId=19596, Sound=11312 WHERE CreatureID=21215 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='No... no! What have you done? I am the master! Do you hear me? I am... aaggh! Can''t... contain him.', BroadcastTextId=19501, Sound=11313 WHERE CreatureID=21215 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='Kill, kill!', BroadcastTextId=19996, Sound=11314 WHERE CreatureID=21215 AND GroupID=5 AND ID=0;
UPDATE world.creature_text SET Text='That''s right, yes!', BroadcastTextId=19997, Sound=11315 WHERE CreatureID=21215 AND GroupID=5 AND ID=1;
UPDATE world.creature_text SET Text='Who''s the master now?', BroadcastTextId=19998, Sound=11316 WHERE CreatureID=21215 AND GroupID=5 AND ID=2;
UPDATE world.creature_text SET Text='You cannot kill me, fools! I''ll be back, I''ll....', BroadcastTextId=19999, Sound=11317 WHERE CreatureID=21215 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text=' I think that we should teach a lesson to both the Horde and the Alliance.  One that they will not soon forget!', BroadcastTextId=19194, Sound=7274 WHERE CreatureID=21504 AND GroupID=6 AND ID=0;
UPDATE world.creature_text SET Text='Why do you aid the Magus? Just think of how many lives could be saved if the portal is never opened, if the resulting wars could be erased....', BroadcastTextId=16814, Sound=10412 WHERE CreatureID=21697 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='You have outstayed your welcome, Keeper. Be gone!', BroadcastTextId=16817, Sound=10413 WHERE CreatureID=21697 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='If you will not cease this foolish quest, then you will die!', BroadcastTextId=16815, Sound=10414 WHERE CreatureID=21697 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='I told you it was a fool''s quest!', BroadcastTextId=16818, Sound=10415 WHERE CreatureID=21697 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Leaving so soon?', BroadcastTextId=16819, Sound=10416 WHERE CreatureID=21697 AND GroupID=3 AND ID=1;
UPDATE world.creature_text SET Text='Time... is on our side.', BroadcastTextId=16816, Sound=10417 WHERE CreatureID=21697 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='Why do you persist? Surely you can see the futility of it all. It is not too late! You may still leave with your lives...', BroadcastTextId=16821, Sound=10442 WHERE CreatureID=21698 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Keeper! The sands of time have run out for you.', BroadcastTextId=16824, Sound=10443 WHERE CreatureID=21698 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='So be it... you have been warned.', BroadcastTextId=16822, Sound=10444 WHERE CreatureID=21698 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='You should have left when you had the chance.', BroadcastTextId=16825, Sound=10445 WHERE CreatureID=21698 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Your days are done.', BroadcastTextId=16826, Sound=10446 WHERE CreatureID=21698 AND GroupID=3 AND ID=1;
UPDATE world.creature_text SET Text='My death means... little.', BroadcastTextId=16823, Sound=10447 WHERE CreatureID=21698 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='At last I am liberated. It has been too long since I have tasted true freedom!', BroadcastTextId=19502, Sound=11309 WHERE CreatureID=21875 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Akama, my friend!  Have you been informed?  I was found out by Vashj''s followers.  Our secret is in peril!', BroadcastTextId=20498, Sound=11611 WHERE CreatureID=22820 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Illidan is looking for me.  I am not safe here... none of us are.', BroadcastTextId=20502, Sound=11612 WHERE CreatureID=22820 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Illidan will find me and when he does... he will pry the Ashtongue secret from me - such is the power of the Betrayer!  No... there is only one way.  My usefulness to the cause has come to an end. I must venture into the spirit world!', BroadcastTextId=20499, Sound=11613 WHERE CreatureID=22820 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='My decision is final.  I will not be dissuaded.  I have devoted my life to our plan.  To jeopardize it now would betray all who have died for the cause long before me.', BroadcastTextId=20500, Sound=11614 WHERE CreatureID=22820 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='I thank you, Akama.  You honor me by allowing me this moment, surrounded by my brothers.  Farewell, friend.  Guide our people well.', BroadcastTextId=20501, Sound=11615 WHERE CreatureID=22820 AND GroupID=4 AND ID=0;
