UPDATE world.creature_text SET Text='Little $n, why do you call me forth? Are you working with the trolls of this land? Have you come to kill me and take my power as your own?', BroadcastTextId=25854, Sound=11557 WHERE CreatureID=26648 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='I sense uncertainty in you, and I do not trust it whether you are with them, or not. If you wish my augury for the Kalu''ak, you will have to prove yourself first.', BroadcastTextId=25863, Sound=11557 WHERE CreatureID=26648 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I will lay a mild compulsion upon you. Jump into the depths before me so that you put yourself into my element and thereby display your submission.', BroadcastTextId=25864, Sound=11557 WHERE CreatureID=26648 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Though you are compelled, the choice, and the last step before you leap, are yours. You have twenty more seconds to decide.', BroadcastTextId=25865, Sound=11557 WHERE CreatureID=26648 AND GroupID=3 AND ID=0;
