UPDATE world.creature_text SET Text='Take a moment and relish this with me. Soon... all will be revealed. Okay then, let''s do this!', BroadcastTextId=30523, Sound=14247 WHERE CreatureID=28070 AND GroupID=9 AND ID=0;
