UPDATE world.creature_text SET Text='I''M FREE, LITTLE DRAKKARI. TIME TO PAY FOR YOUR MANY TRESSPASSES!', BroadcastTextId=29177, Sound=771 WHERE CreatureID=28952 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Once more we hear your call, Khufu. We have wisdom for you and $n. You face great peril and must act swiftly or you all and Har''koa will die.', BroadcastTextId=29233, Sound=643 WHERE CreatureID=29022 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='The gusty essence of deceased Quetz''lun''s wardens must be gathered to draw him near. To Har''koa must both of these rarities be delivered.', BroadcastTextId=29235, Sound=9919 WHERE CreatureID=29023 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='The unblemished heart of the guardian must be secured to show defiance and strength. Jealous Zim''Rhuk keeps those who harbor it.', BroadcastTextId=29234, Sound=473 WHERE CreatureID=29024 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='What is this? I recognize you from when I killed Akali. You must be this $n that everyone is dreading.', BroadcastTextId=29250, Sound=12009 WHERE CreatureID=29028 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='You don''t worry me, $g boy : girl;. Just the opposite - I look forward to killing you. Nothing will stand between me and Zim''Torga now!', BroadcastTextId=29251, Sound=6200 WHERE CreatureID=29028 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='PROPHET!', BroadcastTextId=29269, Sound=643 WHERE CreatureID=29050 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='YOU KEEP YOUR FILTHY DRAKKARI HANDS OFF OF THEM!', BroadcastTextId=29272, Sound=11887 WHERE CreatureID=29050 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='I THINK NOT. YOU WILL DROP YOUR IMMUNITY, CEASE YOUR RITUAL NOW AND RELEASE THEM!', BroadcastTextId=29274, Sound=11883 WHERE CreatureID=29050 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Your sacrifice is a testament to your obedience.  Indeed you are worthy of this charge. Arise, and forever be known as Svala Sorrowgrave!', BroadcastTextId=29688, Sound=14732 WHERE CreatureID=29280 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Your first test awaits you. Destroy our uninvited guests.', BroadcastTextId=29689, Sound=14733 WHERE CreatureID=29280 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='My liege! I have done as you asked, and now beseech you for your blessing!', BroadcastTextId=29684, Sound=13856 WHERE CreatureID=29281 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Glory to Yogg-Saron!', BroadcastTextId=170744, Sound=0 WHERE CreatureID=29310 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='You are unworthy.', BroadcastTextId=170745, Sound=0 WHERE CreatureID=29310 AND GroupID=3 AND ID=1;
