UPDATE world.creature_text SET Text='Threat index threshold exceeded.  Celestial archive aborted. Security level heightened.', BroadcastTextId=0, Sound=13761 WHERE CreatureID=30897 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Additional background is relevant to your query: following global combat between Aesir and Vanir--', BroadcastTextId=0, Sound=13762 WHERE CreatureID=30897 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Unknown. Data suggests that impetus for global combat originated with prime designate Loken, who neutralized all remaining Aesir and Vanir, affecting termination of conflict. Prime designate Loken then initiated stasis of several seed races, including earthen, giants and vrykul, at designated holding facilities.', BroadcastTextId=0, Sound=13763 WHERE CreatureID=30897 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Essentially that is correct.', BroadcastTextId=0, Sound=13764 WHERE CreatureID=30897 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Security breach in progress. Analysis of historical archives transferred to lower-priority queue. Countermeasures engaged.', BroadcastTextId=0, Sound=13756 WHERE CreatureID=30898 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Accessing... Creators arrived to extirpate symbiotic infection. Assessment revealed that Old God infestation had grown malignant. Excising parasites would result in loss of host--', BroadcastTextId=0, Sound=13757 WHERE CreatureID=30898 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='Correct. Creators neutralized parasitic threat and contained it within the host. Forge of Wills and other systems were instituted to create new earthen. Safeguards were implemented, and protectors were appointed.', BroadcastTextId=0, Sound=13758 WHERE CreatureID=30898 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Designations: Aesir and Vanir. Or in the common nomenclature, storm and earth giants. Sentinel Loken designated supreme. Dragon Aspects appointed to monitor evolution on Azeroth.', BroadcastTextId=0, Sound=13759 WHERE CreatureID=30898 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Now fight me, $n! Kill Iskalder!', BroadcastTextId=31540, Sound=1167 WHERE CreatureID=30924 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='Iskalder, there you are. What is this? Engaged in battle already?', BroadcastTextId=31528, Sound=13824 WHERE CreatureID=30945 AND GroupID=0 AND ID=0;
