UPDATE world.creature_text SET Text='I know not how this was possible, but you must still be judged Iskalder. Wait... what is this?', BroadcastTextId=31531, Sound=13824 WHERE CreatureID=30945 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='Stay away from me creature! Do not touch me!', BroadcastTextId=31533, Sound=1168 WHERE CreatureID=30945 AND GroupID=3 AND ID=0;
UPDATE world.creature_text SET Text='Ahahahahahaha! It is done. Return to my cave. We have much to discuss!', BroadcastTextId=31534, Sound=1167 WHERE CreatureID=30945 AND GroupID=4 AND ID=0;
UPDATE world.creature_text SET Text='This? This is me taking control of you. This is me setting up my final revenge!', BroadcastTextId=31532, Sound=13824 WHERE CreatureID=30955 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='I did what I had to, brother. You gave me no alternative.', BroadcastTextId=32626, Sound=14406 WHERE CreatureID=32295 AND GroupID=0 AND ID=0;
UPDATE world.creature_text SET Text='And so ends the Nexus War. ', BroadcastTextId=32627, Sound=14407 WHERE CreatureID=32295 AND GroupID=1 AND ID=0;
UPDATE world.creature_text SET Text='This resolution pains me deeply, but the destruction, the monumental loss of life had to end. Regardless of Malygos'' recent transgressions, I will mourn his loss. He was once a guardian, a protector. This day, one of the world''s mightiest has fallen.', BroadcastTextId=32628, Sound=14408 WHERE CreatureID=32295 AND GroupID=2 AND ID=0;
UPDATE world.creature_text SET Text='The red dragonflight will take on the burden of mending the devastation wrought on Azeroth. Return home to your people and rest. Tomorrow will bring you new challenges, and you must be ready to face them. Life... goes on.', BroadcastTextId=32629, Sound=14409 WHERE CreatureID=32295 AND GroupID=3 AND ID=0;
