UPDATE world.creature_text SET Text='Planetary re-origination? Speak plainly, ye blasted machine!', BroadcastTextId=33910, Sound=15814 WHERE CreatureID=33235 AND GroupID=9 AND ID=0;
UPDATE world.creature_text SET Text='Hear that, lads? It''s only the end of the world! Well, what are ye waiting for, ye rusty machine? Initiate Reply-code Alpha. All is well! Pints are on me!', BroadcastTextId=33911, Sound=15815 WHERE CreatureID=33235 AND GroupID=10 AND ID=0;
